.nav-item:hover .chevron{transform:rotate(180deg)}
.header-actions{display:flex;align-items:center;gap:8px;margin-left:auto}
.btn-ghost{padding:8px 14px;font-size:14px;color:var(--text-secondary);border-radius:6px;transition:all .15s;font-weight:500}
