.mega-menu{position:absolute;top:100%;left:50%;transform:translateX(-50%);background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);padding:24px 28px;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s,visibility .2s;min-width:520px;z-index:200}
