const INITIAL_COUNT = 8;
let visibleCount = INITIAL_COUNT;
let activeCategory = "all";
let searchQuery = "";

function getFilteredPosts() {
  return allPosts.filter(post => {
    const matchCategory = activeCategory === "all" || post.category === activeCategory;
    const q = searchQuery.toLowerCase();
    const matchSearch = !q || post.title.toLowerCase().includes(q) || post.excerpt.toLowerCase().includes(q) || post.author.toLowerCase().includes(q) || post.category.toLowerCase().includes(q);
    return matchCategory && matchSearch;
  });
}

function createPostCard(post) {
  const card = document.createElement("article");
  card.className = "post-card";
  card.innerHTML = `
    <span class="card-tag">${post.category}</span>
    <span class="card-date">${post.date}</span>
    <h4>${post.title}</h4>
    <p>${post.excerpt}</p>
    <div class="card-author">
      <div class="author-avatar">${post.initials}</div>
      ${post.author}
    </div>
  `;
  return card;
}

function renderPosts() {
  const grid = document.getElementById("postsGrid");
  const noResults = document.getElementById("noResults");
  const showMoreWrap = document.getElementById("showMoreWrap");
  const filtered = getFilteredPosts();
  const toShow = filtered.slice(0, visibleCount);

  grid.innerHTML = "";
  toShow.forEach(post => grid.appendChild(createPostCard(post)));

  noResults.classList.toggle("visible", filtered.length === 0);
  showMoreWrap.style.display = visibleCount < filtered.length ? "" : "none";

  // Also filter featured cards
  const featuredCards = document.querySelectorAll(".featured-card");
  const featuredSection = document.getElementById("featuredSection");
  let anyFeaturedVisible = false;

  featuredCards.forEach(card => {
    const cardCategory = card.dataset.category;
    const cardTitle = (card.dataset.title || "").toLowerCase();
    const cardExcerpt = (card.dataset.excerpt || "").toLowerCase();
    const cardAuthor = (card.dataset.author || "").toLowerCase();
    const q = searchQuery.toLowerCase();

    const matchCategory = activeCategory === "all" || cardCategory === activeCategory;
    const matchSearch = !q || cardTitle.includes(q) || cardExcerpt.includes(q) || cardAuthor.includes(q);

    if (matchCategory && matchSearch) {
      card.style.display = "";
      anyFeaturedVisible = true;
    } else {
      card.style.display = "none";
    }
  });

  featuredSection.style.display = anyFeaturedVisible ? "" : "none";
}

// Category filter clicks
document.querySelectorAll(".filter-pill").forEach(pill => {
  pill.addEventListener("click", () => {
    document.querySelectorAll(".filter-pill").forEach(p => p.classList.remove("active"));
    pill.classList.add("active");
    activeCategory = pill.dataset.category;
    visibleCount = INITIAL_COUNT;
    renderPosts();
  });
});

// Search input
document.getElementById("searchInput").addEventListener("input", (e) => {
  searchQuery = e.target.value;
  visibleCount = INITIAL_COUNT;
  renderPosts();
});

